def solve(inp, sepc, arrowcol, starts):
    h=len(inp); w=len(inp[0])
    o=[row[:] for row in inp]
    for r in range(h):
        for c in range(w):
            if inp[r][c] not in (0,sepc,arrowcol):
                o[r][c]=0
    sq={}
    for r in range(h):
        for c in range(w):
            v=inp[r][c]
            if v not in (0,sepc,arrowcol): sq.setdefault(r//5,set()).add(v)
    ar=[]
    # arrow cells: find block containing arrowcol
    arow=next(r for r in range(h) for c in range(w) if inp[r][c]==arrowcol)
    acol=next(c for r in range(h) for c in range(w) if inp[r][c]==arrowcol)
    arow0=(arow//5)*5; acol0=acol//5*5 if False else next(s for s in starts+[w] if s>acol)-5
    for r in range(4):
        for c in range(4):
            if inp[arow0+r][acol0+c]==arrowcol: ar.append((r,c))
    for br,cols in sq.items():
        col=list(cols)[0]
        for bck,s in enumerate(starts):
            for (dr,dc) in ar:
                o[starts[br]+dr][s+dc]=col
    return o
